public final class CuttingRodTest {

    private CuttingRodTest() {
        // Utility class.
    }

    public static void main(String[] args) {
        shouldReturnZeroForNullInput();
        shouldReturnZeroForNonPositiveLength();
        shouldSolveClassicSample();
        shouldSolveShorterRodLength();
        shouldRejectTooSmallPriceTable();
        System.out.println("All CuttingRod tests passed.");
    }

    private static void shouldReturnZeroForNullInput() {
        assertEquals(0, CuttingRod.cutRod(null), "null input");
    }

    private static void shouldReturnZeroForNonPositiveLength() {
        assertEquals(0, CuttingRod.cutRod(new int[] {0, 1, 2}, 0), "rod length 0");
        assertEquals(0, CuttingRod.cutRod(new int[] {0, 1, 2}, -3), "negative rod length");
    }

    private static void shouldSolveClassicSample() {
        int[] samplePrices = {0, 1, 5, 8, 9, 10, 17, 17, 20};
        assertEquals(22, CuttingRod.cutRod(samplePrices), "classic sample");
    }

    private static void shouldSolveShorterRodLength() {
        int[] samplePrices = {0, 1, 5, 8, 9, 10, 17, 17, 20};
        assertEquals(10, CuttingRod.cutRod(samplePrices, 4), "rod length 4");
    }

    private static void shouldRejectTooSmallPriceTable() {
        boolean threw = false;
        try {
            CuttingRod.cutRod(new int[] {0, 1, 5}, 5);
        } catch (IllegalArgumentException expected) {
            threw = true;
        }

        if (!threw) {
            throw new AssertionError("expected IllegalArgumentException for an undersized price table");
        }
    }

    private static void assertEquals(int expected, int actual, String caseName) {
        if (expected != actual) {
            throw new AssertionError(
                    caseName + ": expected " + expected + " but got " + actual);
        }
    }
}

/**
 * Dynamic-programming solution to the rod-cutting problem.
 *
 * The price table is 1-indexed: {@code prices[length]} is the value of a
 * single piece of that length, and {@code prices[0]} is unused.
 */
public final class CuttingRod {

    private CuttingRod() {
        // Utility class.
    }

    public static int cutRod(int[] prices) {
        return prices == null ? 0 : cutRod(prices, defaultRodLength(prices));
    }

    public static int cutRod(int[] prices, int rodLength) {
        if (prices == null || rodLength <= 0) {
            return 0;
        }
        validateInputs(prices, rodLength);

        int[] maxRevenue = new int[rodLength + 1];
        for (int currentLength = 1; currentLength <= rodLength; currentLength++) {
            maxRevenue[currentLength] = bestRevenueForLength(prices, maxRevenue, currentLength);
        }

        return maxRevenue[rodLength];
    }

    private static int defaultRodLength(int[] prices) {
        return prices.length - 1;
    }

    private static void validateInputs(int[] prices, int rodLength) {
        if (prices == null) {
            throw new IllegalArgumentException("prices must not be null");
        }
        if (rodLength < 0) {
            throw new IllegalArgumentException("rodLength must be non-negative");
        }
        if (rodLength >= prices.length) {
            throw new IllegalArgumentException(
                    "rodLength must be less than prices.length for a 1-indexed price table");
        }
    }

    private static int bestRevenueForLength(int[] prices, int[] maxRevenue, int currentLength) {
        int bestForLength = 0;
        for (int firstCut = 1; firstCut <= currentLength; firstCut++) {
            bestForLength = Math.max(
                    bestForLength,
                    prices[firstCut] + maxRevenue[currentLength - firstCut]);
        }
        return bestForLength;
    }
}

